'use strict';
/** Official Paigaam brand assets, base64-embedded (5 files incl @2x).
 * ensureBrandAssets() heals any missing/corrupt file at boot.
 * Binaries can't survive text-only git APIs, so we carry them as data. */
const fs = require("node:fs");
const path = require("node:path");
const BRAND = {
  "logo-full.png": "",
  "logo-full@2x.png": "",
  "dove.png": "",
  "dove@2x.png": "",
  "favicon-512.png": "",
};

const MAGIC = Buffer.from([0x89, 0x50, 0x4e, 0x47]); // PNG
function ensureBrandAssets() {
  const dir = path.join(__dirname, "..", "public", "brand");
  fs.mkdirSync(dir, { recursive: true });
  const written = [];
  for (const [name, b64] of Object.entries(BRAND)) {
    const file = path.join(dir, name);
    const cur = fs.existsSync(file) ? fs.readFileSync(file) : null;
    const valid = cur && cur.length > 8 && cur.subarray(0, 4).equals(MAGIC);
    if (!valid) { fs.writeFileSync(file, Buffer.from(b64, "base64")); written.push(name); }
  }
  return written;
}
ensureBrandAssets();
module.exports = { ensureBrandAssets };
